<script setup>
import { computed, defineAsyncComponent, ref, watch } from 'vue';
const pages={child:defineAsyncComponent(()=>import('./Child.vue')),parent:defineAsyncComponent(()=>import('./Parent.vue')),platform:defineAsyncComponent(()=>import('./Platform.vue')),index:defineAsyncComponent(()=>import('./Entry.vue'))};
const end=document.body.dataset.end||'index';
const menu={child:[['home','dashboard','今天学什么'],['homework','camera','拍作业'],['mistakes','book','错题订正'],['review','clipboard','到期复习'],['handwriting','pencil','工整度反馈'],['preview','sparkles','明日预习'],['pairing','link','设备与授权']],parent:[['overview','dashboard','家庭概览'],['submissions','clipboard','作业与核对'],['mistakes','book','错题与复习'],['reports','chart','学习报告'],['tutoring','sparkles','学习讲解'],['handwriting','pencil','书写观察'],['schedule','calendar','课表与教材'],['privacy','shield','家庭与隐私']],platform:[['ops','dashboard','运行概览'],['tenants','layers','家庭租户'],['jobs','activity','任务队列'],['people','users','学生与家长'],['schools','school','学校管理'],['books','library','教材与解析'],['models','cpu','模型与评测'],['admins','lock','账号与权限'],['audit','shield','安全审计']]};
const nav=menu[end]||[];
const active=ref(nav.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):nav[0]?.[0]);
const mobileMenu=ref(false),notices=ref(false),guide=ref(false);
const current=computed(()=>nav.find(n=>n[0]===active.value));
const title={child:'学习空间',parent:'家长工作台',platform:'平台管理中心'};
function go(id){active.value=id;mobileMenu.value=false;location.hash=id;window.scrollTo(0,0);}
window.addEventListener('hashchange',()=>{if(nav.some(n=>n[0]===location.hash.slice(1)))active.value=location.hash.slice(1);});
watch(()=>active.value,()=>document.title=`${current.value?.[2]||''} · 小知 Wizzy`);
</script>
<template><component v-if="end==='index'" :is="pages.index"/><div v-else class="app-shell" :class="[end,{'menu-open':mobileMenu}]"><aside class="app-sidebar"><a class="brand" href="index.html"><span class="brand-mark">知<span /></span><span>小知 <b>Wizzy</b><small>{{end==='platform'?'PLATFORM CONSOLE':'LEARNING COMPANION'}}</small></span></a><div class="workspace"><span class="workspace-icon"><Icon :name="end==='platform'?'layers':end==='parent'?'heart':'sparkles'" /></span><div><strong>{{end==='platform'?'小知运营空间':end==='parent'?'我的家庭':'我的学习空间'}}</strong><small>{{end==='platform'?'演示环境 · 元数据权限':end==='parent'?'家庭所有者 · 演示':'三年级 · 上学期'}}</small></div></div><div class="nav-label">{{end==='platform'?'WORKSPACE / 工作空间':'LEARNING / 陪伴成长'}}</div><nav class="side-nav" aria-label="主导航"><button v-for="(item,i) in nav" :key="item[0]" :class="{active:active===item[0], 'nav-separator':end==='platform'&&[3,7].includes(i)}" :aria-current="active===item[0]?'page':undefined" @click="go(item[0])"><Icon :name="item[1]" /><span>{{item[2]}}</span><span v-if="item[0]==='submissions'" class="nav-count">3</span><Icon v-if="active===item[0]" name="right" :size="15" /></button></nav><div class="sidebar-bottom"><div class="privacy-card"><Icon :name="end==='child'?'heart':'shield'" :size="22"/><strong>{{end==='child'?'按自己的节奏，慢慢来':'数据安全，始终优先'}}</strong><p>{{end==='child'?'每一次认真尝试，都值得被看见。':'仅使用虚构数据。此处的端切换不代表真实权限切换。'}}</p></div><button class="support-button" @click="guide=true"><Icon name="help" :size="18" />原型说明与操作指南<Icon name="up" :size="15"/></button><div class="profile"><span class="avatar">{{end==='child'?'林':end==='parent'?'家':'运'}}</span><div><strong>{{end==='child'?'林同学':end==='parent'?'林同学的家长':'运营演示账号'}}</strong><small>{{end==='platform'?'MFA · 真实认证未接入':'交互原型 · 不连接真实账号'}}</small></div></div></div></aside><button v-if="mobileMenu" class="menu-shade" aria-label="关闭菜单" @click="mobileMenu=false"/><div class="app-body"><header class="app-topbar"><div class="breadcrumb"><button class="icon-button mobile-toggle" aria-label="展开导航" @click="mobileMenu=!mobileMenu"><Icon name="menu"/></button><span>{{title[end]}}</span><Icon name="right" :size="14"/><strong>{{current?.[2]}}</strong></div><div class="topbar-actions"><span class="environment"><i/>交互演示</span><nav class="end-switch" aria-label="原型端切换"><a v-for="(label,key) in {child:'孩子端',parent:'家长端',platform:'平台端'}" :key="key" :href="`${key}.html`" :class="{active:end===key}">{{label}}</a></nav><button class="icon-button notification" aria-label="查看通知" @click="notices=true"><Icon name="bell"/><i/></button><span class="top-avatar">{{end==='platform'?'运':'林'}}</span></div></header><main class="main-content"><component :is="pages[end]" :tab="active" @navigate="go"/></main><footer class="app-footer"><span>小知 Wizzy · 让每一次努力都有回应</span><span>虚构演示数据 · 不上传文件 · 不调用 AI</span></footer></div><el-drawer v-model="notices" title="通知中心" size="min(420px, 100%)"><div class="notice-item"><span class="soft-icon amber"><Icon name="alert"/></span><div><strong>{{end==='platform'?'供应商延迟预警':'有 3 道题等待家长核对'}}</strong><p>{{end==='platform'?'演示：vision-2.4 响应耗时升高，请前往任务队列查看。':'待确认不等于做错，也不会计入错题率。'}}</p><el-button type="primary" link @click="go(end==='platform'?'jobs':end==='parent'?'submissions':'homework');notices=false">前往查看 →</el-button></div></div><el-alert title="这些是原型固定通知，不是实时消息。" :closable="false" type="info"/></el-drawer><el-dialog v-model="guide" title="原型操作指南" width="560px"><p>从左侧导航进入各功能。表格支持搜索、状态筛选、分页与详情；新增记录和保存表单会改变本次会话的数据，刷新后恢复演示状态。</p><p>教材流程：选择自有授权 PDF → 登记权利依据 → 模拟解析 → 查看 TXT 和源页映射 → 提交抽检。模型登记后必须经过评测和独立审批，原型不会直接发布生产版本。</p><el-alert title="这是采用真实 UI 组件库的高保真交互原型，不是已接入后台、真实认证、数据库、OCR 或 AI 的商用系统。" type="warning" :closable="false" show-icon/><template #footer><el-button type="primary" @click="guide=false">开始体验</el-button></template></el-dialog></div></template>
